data.query:
query Query($where: InventoryWhereInput) {
  inventory(where: $where) {
    edges {
      node {
        id
				active
        barcode
        number


        inventoryStatus {
          id
          name
          active
          suspect
          containment
          productionLoaded

        }
        quantity {
          value
          unitId
        }
        weightUnit {
          id
          code
        }
        grossWeight
        netWeight
        tareWeight

        masterInventory {
          id
          number
          masterInventoryStatus {
            id
            name
            active
            containment

          }
        }

        productStrategyProcess {
          id
          code          
          unitWeight
          productStrategy {
            id
            code
            name
            product {
              id
              code
              name
            }
          }
        }
      }
    }
  }
}

